bool connectToDatabase(MYSQL* conn, const std::string& host, const std::string& user,
                       const std::string& password, const std::string& database) {
    mysql_init(conn);
    if (mysql_real_connect(conn, host.c_str(), user.c_str(), password.c_str(),
                          database.c_str(), 0, nullptr, 0) == nullptr) {
        std::cerr << "Connection failed: " << mysql_error(conn) << std::endl;
        return false;
    }
    return true;
}

UserInfo* queryUserByUsername(MYSQL* conn, const std::string& username, bool& success) {
    success = false;
    MYSQL_STMT* stmt = mysql_stmt_init(conn);
    if (!stmt) {
        std::cerr << "Statement initialization failed: " << mysql_error(conn) << std::endl;
        return nullptr;
    }

    const char* query = "SELECT id, username, email, full_name FROM users WHERE username = ?";
    if (mysql_stmt_prepare(stmt, query, static_cast<unsigned long>(strlen(query)))) {
        std::cerr << "Prepare failed: " << mysql_stmt_error(stmt) << std::endl;
        mysql_stmt_close(stmt);
        return nullptr;
    }

    MYSQL_BIND param_bind[1];
    memset(param_bind, 0, sizeof(param_bind));
    unsigned long param_len = static_cast<unsigned long>(username.length());

    param_bind[0].buffer_type = MYSQL_TYPE_STRING;
    param_bind[0].buffer = const_cast<char*>(username.c_str());
    param_bind[0].buffer_length = param_len;
    param_bind[0].is_null = nullptr;
    param_bind[0].length = &param_len;

    if (mysql_stmt_bind_param(stmt, param_bind)) {
        std::cerr << "Bind parameter failed: " << mysql_stmt_error(stmt) << std::endl;
        mysql_stmt_close(stmt);
        return nullptr;
    }

    if (mysql_stmt_execute(stmt)) {
        std::cerr << "Execute failed: " << mysql_stmt_error(stmt) << std::endl;
        mysql_stmt_close(stmt);
        return nullptr;
    }

    if (mysql_stmt_store_result(stmt)) {
        std::cerr << "Store result failed: " << mysql_stmt_error(stmt) << std::endl;
        mysql_stmt_close(stmt);
        return nullptr;
    }

    UserInfo* user = new UserInfo();
    char username_buf[256] = {0};
    char email_buf[256] = {0};
    char full_name_buf[256] = {0};
    unsigned long username_len = 0, email_len = 0, full_name_len = 0;
    my_bool username_is_null = 0, email_is_null = 0, full_name_is_null = 0;

    MYSQL_BIND result_bind[4];
    memset(result_bind, 0, sizeof(result_bind));

    result_bind[0].buffer_type = MYSQL_TYPE_LONG;
    result_bind[0].buffer = &user->id;
    result_bind[0].is_null = nullptr;

    result_bind[1].buffer_type = MYSQL_TYPE_STRING;
    result_bind[1].buffer = username_buf;
    result_bind[1].buffer_length = sizeof(username_buf);
    result_bind[1].length = &username_len;
    result_bind[1].is_null = &username_is_null;

    result_bind[2].buffer_type = MYSQL_TYPE_STRING;
    result_bind[2].buffer = email_buf;
    result_bind[2].buffer_length = sizeof(email_buf);
    result_bind[2].length = &email_len;
    result_bind[2].is_null = &email_is_null;

    result_bind[3].buffer_type = MYSQL_TYPE_STRING;
    result_bind[3].buffer = full_name_buf;
    result_bind[3].buffer_length = sizeof(full_name_buf);
    result_bind[3].length = &full_name_len;
    result_bind[3].is_null = &full_name_is_null;

    if (mysql_stmt_bind_result(stmt, result_bind)) {
        std::cerr << "Bind result failed: " << mysql_stmt_error(stmt) << std::endl;
        delete user;
        mysql_stmt_close(stmt);
        return nullptr;
    }

    int fetch_status = mysql_stmt_fetch(stmt);
    if (fetch_status == MYSQL_NO_DATA) {
        delete user;
        mysql_stmt_close(stmt);
        return nullptr;
    }

    if (fetch_status != 0) {
        std::cerr << "Fetch failed: " << mysql_stmt_error(stmt) << std::endl;
        delete user;
        mysql_stmt_close(stmt);
        return nullptr;
    }

    if (!username_is_null) {
        user->username.assign(username_buf, username_len);
    }
    if (!email_is_null) {
        user->email.assign(email_buf, email_len);
    }
    if (!full_name_is_null) {
        user->full_name.assign(full_name_buf, full_name_len);
    }

    mysql_stmt_close(stmt);
    success = true;
    return user;
}

